// Surface notification failures in the execution log. We do NOT mark matches
// notified on failure, so the next run will retry those users safely.
const msg = $json.execution?.error?.message || 'unknown notification error';
const wf = $json.workflow?.name || 'C - User Notification';
console.log(`[notify-error] workflow='${wf}' message='${msg}'`);
return [{ json: { workflow: wf, error: msg } }];
